<?php

declare(strict_types=1);
namespace App\Tools\DifalIcmsCalculator\Presentation\Controllers;
use App\Core\Access\Services\ToolPersistenceAuthorizer; use App\Core\Dates\ReferenceDate; use App\Core\Export\Data\PrintableDocument; use App\Core\Export\Services\{BrowserPrintExporter,TabularExportService}; use App\Core\Tools\History\Contracts\ToolRunRecorder; use App\Core\Tools\History\Data\{RuleVersion,ToolRunHandle}; use App\Http\Controllers\Controller; use App\Tools\DifalIcmsCalculator\Application\Data\CalculationInput; use App\Tools\DifalIcmsCalculator\Domain\Services\Calculator; use App\Tools\DifalIcmsCalculator\Presentation\Requests\ExecuteToolRequest; use App\Tools\DifalIcmsCalculator\Tool; use Illuminate\Contracts\View\View; use Illuminate\Http\{Request,Response}; use Symfony\Component\HttpFoundation\StreamedResponse; use Throwable;
final class ToolController extends Controller { public function index(): View { return view('tools-calculadora-difal-icms::index'); } public function calculate(ExecuteToolRequest $request,Calculator $calculator,ToolRunRecorder $recorder,ToolPersistenceAuthorizer $persistence,Tool $module): View { $input=$this->input($request->validated()); $run=$this->startRun($request,$recorder,$persistence,$module,$input); try{$result=$calculator->calculate($input); if($run)$recorder->succeed($run,$result->toArray()); return view('tools-calculadora-difal-icms::index',['result'=>$result,'historySaved'=>(bool)$run]);}catch(Throwable $e){if($run)$recorder->fail($run,$e->getMessage()); throw $e;} } public function printCurrent(ExecuteToolRequest $request,Calculator $calculator,BrowserPrintExporter $print): View { $d=$request->validated(); $r=$calculator->calculate($this->input($d)); return $print->render(new PrintableDocument('Relatório DIFAL / ICMS / FCP','tools-calculadora-difal-icms::report',['result'=>$r],$d['origin_uf'].' → '.$d['destination_uf'],now()->format('d/m/Y H:i'),'Total destino',$r->summary[4]->value)); } public function exportCurrent(ExecuteToolRequest $request,Calculator $calculator,TabularExportService $export): Response|StreamedResponse { $r=$calculator->calculate($this->input($request->validated())); return $export->csv('difal-icms-'.now()->format('Y-m-d').'.csv',['Campo','Valor'],array_map(static fn($i)=>[$i->label,$i->value],$r->summary)); } private function input(array $d): CalculationInput { return new CalculationInput($d['competence'],$d['base'],$d['origin_uf'],$d['destination_uf'],(bool)($d['imported']??false),isset($d['interstate_rate'])&&(string)$d['interstate_rate']!==''?(string)$d['interstate_rate']:null,(string)$d['internal_rate'],(string)($d['fcp_rate']??'0'),(string)$d['method'],(bool)($d['recipient_taxpayer']??false)); } private function startRun(Request $request,ToolRunRecorder $recorder,ToolPersistenceAuthorizer $persistence,Tool $module,CalculationInput $input): ?ToolRunHandle { if(!$request->user()||!$persistence->allowsHistory($module,$request->user())) return null; return $recorder->start($module,new RuleVersion('2026.1.0'),ReferenceDate::fromString($input->competence.'-01'),$input->toArray(),$request->user()->id); } }
